"""ZAIOS SYSTEM v1.1 · manual de identidade (HTML → PDF) e exemplos de aplicação (HTML → PNG).
Uso: python3 producao/brand-zaios/gerar_manual.py <pasta do kit>  (depois: node producao/brand-zaios/render_manual.js <pasta do kit>)"""
import sys, json, pathlib, base64
K = pathlib.Path(sys.argv[1]); RAIZ = pathlib.Path(__file__).resolve().parents[2]
M = json.loads((K / "manifesto.json").read_text()); PAL = json.loads((K / "paleta.json").read_text()); P = M["paleta"]
f64 = lambda p: base64.b64encode(p.read_bytes()).decode()
FONTE = f"@font-face{{font-family:Aventa;src:url(data:font/woff2;base64,{f64(RAIZ / 'docs/assets/fonts/aventa.woff2')}) format('woff2');font-weight:100 900}}"
def svg(n):
    t = (K / "svg" / f"{n}.svg").read_text(); i = t.index(">")
    return t[:i].replace(' width="', ' data-w="').replace(' height="', ' data-h="') + t[i:]  # só no elemento <svg>, preservando o retângulo de fundo
def img(n, estilo=""): return f'<div class="lg" style="{estilo}">{svg(n)}</div>'
CSS = f"""{FONTE}
*{{margin:0;box-sizing:border-box}} body{{font-family:Aventa,sans-serif;color:{P['preto']};background:#fff}}
.lg svg{{width:100%;height:auto;display:block}}
.pg{{width:297mm;height:210mm;padding:16mm 18mm;page-break-after:always;position:relative;overflow:hidden}}
.esc{{background:{P['preto']};color:{P['marfim']}}} .esc h2,.esc .k{{color:{P['dourado']}}}
.k{{font-weight:700;letter-spacing:.22em;text-transform:uppercase;font-size:9pt;color:#8a7440}}
h1{{font-weight:700;font-size:34pt;letter-spacing:.01em}} h2{{font-weight:700;font-size:20pt;margin:3mm 0 6mm}}
p,li,td,th{{font-size:10pt;line-height:1.45;font-weight:400}} .muted{{opacity:.75}}
.g2{{display:grid;grid-template-columns:1fr 1fr;gap:8mm}} .g3{{display:grid;grid-template-columns:repeat(3,1fr);gap:6mm}}
.cx{{border:1px solid #ddd;padding:5mm;border-radius:2mm}} .rod{{position:absolute;bottom:9mm;left:18mm;right:18mm;font-size:8pt;opacity:.6;display:flex;justify-content:space-between}}
table{{border-collapse:collapse;width:100%}} td,th{{border-bottom:1px solid #e5e0d4;padding:2mm 2mm;text-align:left}} th{{font-weight:700}}
.sw{{height:22mm;border-radius:2mm;border:1px solid #ddd}} .x{{color:#b3261e;font-weight:700}}
"""
def pg(conteudo, escura=False, n=""):
    return f'<section class="pg {"esc" if escura else ""}">{conteudo}<div class="rod"><span>ZAIOS SYSTEM · Manual de identidade v1.1 · proposta para aprovação</span><span>{n}</span></div></section>'
cores = "".join(f'<div><div class="sw" style="background:{c["hex"]}"></div><p><b>{c["nome"]}</b><br>{c["hex"]} · RGB {", ".join(map(str, c["rgb"]))}<br>CMYK aprox. {"/".join(map(str, c["cmyk_aproximado"]))}<br><span class="muted">{c["token"]}</span></p></div>' for c in PAL["cores"])
contr = "".join(f'<tr><td>{x["texto"]}</td><td>{x["fundo"]}</td><td>{x["razao"]:.2f}:1</td><td>{"Texto (AA)" if x["AA_texto_normal"] else ("Só títulos grandes" if x["AA_texto_grande"] else "<span class=x>Só decorativo</span>")}</td></tr>' for x in PAL["contrastes"])
paginas = [
 pg(f'<div style="display:flex;flex-direction:column;justify-content:center;height:100%;gap:12mm"><div style="width:62%">{img("zaios-system-horizontal-com-descricao-transparente-dourado")}</div><div><p class="k">Manual de identidade · versão 1.1</p><p class="muted" style="margin-top:2mm">Proposta para aprovação de Bruno Chaerk · Zion Hotel Group International</p></div></div>', True, "1"),
 pg(f'<p class="k">Princípios</p><h2>Uma marca de plataforma, filha da Zion</h2><div class="g2"><div><p><b>Posicionamento.</b> A plataforma de inteligência para desenvolvimento, gestão e operação hoteleira.</p><p style="margin-top:3mm"><b>Símbolo.</b> O Z original de três barras da Zion Hotel Group International. Não existe outro Z: nenhuma variação de desenho, volume, fita ou brilho.</p><p style="margin-top:3mm"><b>Estilo.</b> Minimalista, sofisticado e tecnológico. Formas planas, cores sólidas, muito respiro. Sem brilhos, sombras, gradientes metálicos ou efeitos 3D.</p><p style="margin-top:3mm"><b>Assinatura.</b> ZAIOS SYSTEM. A descrição institucional acompanha a assinatura quando houver espaço; na interface, usar a versão reduzida ou o símbolo.</p></div><div class="cx">{img("zaios-system-vertical-com-descricao-fundo-preto")}</div></div>', False, "2"),
 pg(f'<p class="k">Símbolo</p><h2>Construção, respiro e tamanho mínimo</h2><div class="g2"><div class="cx" style="background:repeating-linear-gradient(0deg,#f3efe6 0 1px,transparent 1px 25%),repeating-linear-gradient(90deg,#f3efe6 0 1px,transparent 1px 25%)">{img("zaios-simbolo-transparente-preto")}</div><div><p>O símbolo foi vetorizado a partir do logotipo oficial da Zion (Z de 240 px; precisão de ±0,5 px, ou 0,2% da altura), em grade de 240 × 240. São três barras: superior (1/4 da altura), central com a diagonal e inferior (1/8), com cortes diagonais paralelos.</p><p style="margin-top:3mm"><b>Área de respiro (X).</b> X = 1/4 da altura do símbolo, igual à altura da barra superior. Nenhum texto, borda ou imagem entra nessa área.</p><p style="margin-top:3mm"><b>Tamanho mínimo</b> (verificado na tela, em 1×): horizontal reduzida, 160 px ou 40 mm; vertical reduzida, 140 px ou 35 mm; versões com descrição, 600 px ou 150 mm (abaixo disso, usar a reduzida); símbolo transparente, 24 px ou 6 mm; favicon com fundo, 16 px. Abaixo de 160 px, usar só o símbolo.</p><p style="margin-top:3mm"><b>Linha divisória.</b> Na horizontal, a linha vertical vai do topo à base do símbolo e para aí. A descrição institucional fica numa faixa própria, abaixo, sem cruzar a linha nem o símbolo.</p></div></div>', False, "3"),
 pg(f'<p class="k">Versões</p><h2>Horizontal e vertical, com descrição e reduzida</h2><div class="g2"><div class="cx" style="background:{P["preto"]}">{img("zaios-system-horizontal-com-descricao-transparente-dourado")}</div><div class="cx" style="background:{P["preto"]}">{img("zaios-system-horizontal-reduzida-transparente-dourado")}</div></div><div class="g3" style="margin-top:6mm"><div class="cx" style="background:{P["preto"]}">{img("zaios-system-vertical-com-descricao-transparente-dourado")}</div><div class="cx" style="background:{P["preto"]}">{img("zaios-system-vertical-reduzida-transparente-dourado")}</div><div><p><b>Com descrição:</b> materiais comerciais, apresentações, capas, assinatura institucional.</p><p style="margin-top:3mm"><b>Reduzida:</b> interface, menus, cabeçalhos, espaços estreitos.</p><p style="margin-top:3mm"><b>Símbolo isolado:</b> ícone do aplicativo, favicon, avatar.</p></div></div>', False, "4"),
 pg(f'<p class="k">Fundos</p><h2>Cor da marca por fundo</h2><div class="g3"><div>{img("zaios-system-horizontal-reduzida-fundo-preto")}<p>Preto profundo: símbolo e texto em dourado.</p></div><div>{img("zaios-system-horizontal-reduzida-fundo-verde")}<p>Verde Zion: símbolo dourado, texto marfim.</p></div><div>{img("zaios-system-horizontal-reduzida-fundo-marfim")}<p>Marfim: símbolo e texto em preto; dourado só na linha.</p></div><div class="cx" style="background:#5b6b63">{img("zaios-system-horizontal-reduzida-mono-branco")}<p style="color:#fff">Monocromática branca sobre fotos e fundos escuros.</p></div><div class="cx">{img("zaios-system-horizontal-reduzida-mono-preto")}<p>Monocromática preta: impressão em uma cor, documentos.</p></div><div><p>Versões transparentes (PNG e SVG) em dourado, preto e branco para aplicar sobre fundos da paleta. Sobre fotos, usar a monocromática branca com área calma atrás da marca.</p></div></div>', False, "5"),
 pg(f'<p class="k">Paleta</p><h2>Cores oficiais v1.1 (proposta de referência)</h2><div style="display:grid;grid-template-columns:repeat(5,1fr);gap:5mm">{cores}</div><table style="margin-top:6mm"><tr><th>Texto</th><th>Fundo</th><th>Contraste</th><th>Uso</th></tr>{contr}</table><p class="muted" style="margin-top:2mm">Contraste pelo critério WCAG 2 (AA: 4,5:1 para texto, 3:1 para títulos grandes). CMYK por conversão direta; validar prova de cor com a gráfica.</p>', False, "6"),
 pg(f'<p class="k">Tipografia</p><h2>Aventa</h2><div class="g2"><div><p style="font-weight:700;font-size:40pt;line-height:1">Aventa Bold</p><p class="muted">Assinatura ZAIOS, títulos</p><p style="font-weight:500;font-size:26pt;margin-top:6mm">Aventa Medium</p><p class="muted">SYSTEM, descrição institucional, subtítulos</p><p style="font-weight:400;font-size:20pt;margin-top:6mm">Aventa Regular</p><p class="muted">Textos corridos e interface</p></div><div><p style="font-weight:500;font-size:14pt;letter-spacing:.4em">S Y S T E M</p><p class="muted">Espaçamento de 0,40 em entre letras na palavra SYSTEM</p><p style="font-size:12pt;margin-top:6mm">ABCDEFGHIJKLMNOPQRSTUVWXYZ<br>abcdefghijklmnopqrstuvwxyz<br>0123456789 · ãçéêíóôõú · R$ % / ·</p><p style="margin-top:6mm">Arquivo original: Aventa Variable (pesos 100 a 900), já fornecido. Nos logotipos o texto está convertido em curvas: não depende da fonte instalada. A fonte não é redistribuída neste kit.</p></div></div>', False, "7"),
 pg(f'<p class="k">Usos incorretos</p><h2>O que não fazer</h2><div class="g3">' + "".join(f'<div><div class="cx" style="background:{bg};overflow:hidden"><div style="{st}">{img(n)}</div></div><p class="x" style="margin-top:2mm">{t}</p></div>' for n, bg, st, t in [
   ("zaios-system-horizontal-reduzida-transparente-dourado", P["preto"], "transform:scaleX(1.35);transform-origin:left", "Distorcer ou esticar"),
   ("zaios-system-horizontal-reduzida-transparente-dourado", P["preto"], "filter:drop-shadow(4px 6px 3px rgba(255,255,255,.45))", "Sombras, brilhos ou 3D"),
   ("zaios-system-horizontal-reduzida-transparente-dourado", P["marfim"], "", "Dourado sobre marfim (contraste 1,6:1)"),
   ("zaios-system-horizontal-reduzida-transparente-dourado", P["preto"], "transform:rotate(-8deg)", "Girar ou inclinar"),
   ("zaios-system-horizontal-reduzida-mono-branco", "#c9372c", "", "Cores fora da paleta"),
   ("zaios-system-horizontal-reduzida-transparente-dourado", "linear-gradient(90deg,#1b6fd1,#e0a12a)", "", "Fundos com degradê ou ruído atrás da marca")]) + '</div><p style="margin-top:4mm">Também é proibido: redesenhar o Z ou trocar por outro símbolo; usar ® sem confirmação do registro; deixar a linha divisória cruzar a descrição; mudar a fonte da assinatura.</p>', False, "8"),
 pg('<p class="k">Aplicações</p><h2>Exemplos de uso</h2><div class="g3">' + "".join(f'<div><img src="aplicacoes/{n}.png" style="width:100%;border:1px solid #ddd;border-radius:2mm"><p>{t}</p></div>' for n, t in [("01-login", "Tela de entrada da plataforma"), ("02-painel", "Menu da plataforma (versão reduzida)"), ("03-icone-favicon", "Ícone do aplicativo e favicon"), ("04-cartao", "Cartão de visita, frente e verso"), ("05-capa-modulo", "Capa de módulo na área de membros"), ("06-assinatura-email", "Assinatura de e-mail e avatar")]) + '</div>', False, "9"),
 pg('<p class="k">Arquivos e notas técnicas</p><h2>Conteúdo do kit</h2><div class="g2"><div><p><b>svg/</b> todas as versões em vetor, com o texto em curvas.</p><p><b>png/</b> as mesmas versões em PNG transparente ou com fundo (assinaturas em 2400 e 1200 px; símbolo em 1024 e 256 px; ícones em 1024, 512 e 180 px; favicon em 16, 32, 48, 180, 192 e 512 px).</p><p><b>zaios-favicon.ico</b> (16, 32 e 48 px) · <b>tokens.css</b> e <b>tokens.json</b> · <b>paleta.json</b> · <b>aplicacoes/</b> · este manual em PDF.</p></div><div><p><b>Origem do símbolo.</b> Vetorizado do logotipo oficial da Zion em PNG (1214 × 320). Se existir o arquivo vetorial original (AI ou SVG) da Zion, comparar e substituir antes da produção gráfica em grande formato.</p><p style="margin-top:3mm"><b>Paleta.</b> Valores propostos pelo Bruno como referência da v1.1. Aguardam aprovação.</p><p style="margin-top:3mm"><b>Diferenças em relação à v1.0.</b> Um único Z, o oficial; uma única tabela de cores; linha divisória limitada ao símbolo; descrição em faixa própria; versões vertical e reduzida; SVG; manual.</p></div></div>', False, "10"),
]
(K / "manual.html").write_text(f'<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><title>ZAIOS SYSTEM · Manual v1.1</title><style>{CSS}@page{{size:A4 landscape;margin:0}}</style></head><body>{"".join(paginas)}</body></html>')
# ---------- aplicações (HTML individuais) ----------
A = K / "aplicacoes"; A.mkdir(exist_ok=True)
base = lambda w, h, corpo, bg="#fff": f'<!doctype html><html><head><meta charset="utf-8"><style>{CSS} body{{width:{w}px;height:{h}px;background:{bg};overflow:hidden}}</style></head><body>{corpo}</body></html>'
pd, dg, mf, vd, gf = P["preto"], P["dourado"], P["marfim"], P["verde"], P["grafite"]
apps = {
 "01-login": (1440, 900, f'<div style="display:grid;grid-template-columns:1.1fr 1fr;height:100%"><div style="background:{pd};display:flex;align-items:center;justify-content:center"><div style="width:62%">{img("zaios-system-vertical-com-descricao-transparente-dourado")}</div></div><div style="background:{mf};display:flex;flex-direction:column;justify-content:center;padding:0 120px;gap:22px"><p style="font-weight:700;font-size:34px">Entrar</p><p style="font-size:16px;color:{gf}">Use o e-mail cadastrado. Enviamos um link de acesso.</p><div style="border:1px solid #bfb6a3;border-radius:8px;padding:18px;font-size:16px;color:#7a7266;background:#fff">voce@exemplo.com</div><div style="background:{pd};color:{dg};border-radius:8px;padding:18px;text-align:center;font-weight:700;font-size:16px;letter-spacing:.06em">RECEBER LINK DE ACESSO</div></div></div>'),
 "02-painel": (1440, 900, f'<div style="display:grid;grid-template-columns:300px 1fr;height:100%;background:{gf}"><div style="background:{pd};padding:36px 28px"><div style="width:190px">{img("zaios-system-horizontal-reduzida-transparente-dourado")}</div><div style="margin-top:46px;display:flex;flex-direction:column;gap:6px">' + "".join(f'<div style="padding:13px 16px;border-radius:8px;font-size:16px;{"background:#1a1a1a;color:" + dg if i == 0 else "color:" + mf}">{t}</div>' for i, t in enumerate(["Início", "Desenvolvimento", "Gestão", "Operação", "Academy", "Suporte"])) + f'</div></div><div style="padding:56px"><p style="color:{mf};font-weight:700;font-size:34px">Olá, associado</p><p style="color:{mf};opacity:.7;font-size:16px;margin-top:6px">Escolha por onde continuar.</p><div style="display:grid;grid-template-columns:repeat(3,1fr);gap:22px;margin-top:40px">' + "".join(f'<div style="background:{pd};border:1px solid #333;border-radius:12px;padding:28px"><div style="width:44px;height:4px;background:{dg}"></div><p style="color:{mf};font-weight:700;font-size:22px;margin-top:18px">{t}</p><p style="color:{mf};opacity:.65;font-size:14px;margin-top:8px">{s}</p></div>' for t, s in [("Desenvolvimento", "Do terreno ao projeto"), ("Gestão", "Números e rotina do mês"), ("Operação", "Padrão e equipe")]) + '</div></div></div>'),
 "03-icone-favicon": (1440, 900, f'<div style="display:grid;grid-template-columns:1fr 1fr;height:100%;background:{mf}"><div style="display:flex;align-items:center;justify-content:center"><div style="width:380px;height:760px;border-radius:56px;background:{vd};padding:70px 30px;display:grid;grid-template-columns:repeat(4,68px);justify-content:space-between;row-gap:26px;align-content:start">' + "".join(f'<div><div style="width:68px;height:68px;border-radius:16px;overflow:hidden;background:{"#2e5a4e" if i != 5 else pd}">{img("zaios-icone-app-preto-dourado") if i == 5 else ""}</div><p style="color:#fff;font-size:11px;text-align:center;margin-top:6px">{"ZAIOS" if i == 5 else ""}</p></div>' for i in range(16)) + f'</div></div><div style="display:flex;align-items:center;justify-content:center"><div style="width:560px;background:#fff;border-radius:12px;box-shadow:0 0 0 1px #d8d0bf"><div style="display:flex;gap:10px;align-items:center;background:#ece7dc;border-radius:12px 12px 0 0;padding:12px 16px"><div style="display:flex;align-items:center;gap:10px;background:#fff;border-radius:8px;padding:8px 14px;width:280px"><img src="../png/zaios-favicon-32.png" style="width:18px;height:18px"><span style="font-size:14px">ZAIOS SYSTEM</span></div></div><div style="height:220px;display:flex;align-items:center;justify-content:center"><img src="../png/zaios-favicon-192.png" style="width:96px"></div></div></div></div>'),
 "04-cartao": (1440, 900, f'<div style="height:100%;background:#d9d2c3;display:flex;align-items:center;justify-content:center;gap:60px"><div style="width:540px;height:320px;background:{pd};border-radius:10px;display:flex;align-items:center;justify-content:center"><div style="width:120px">{img("zaios-simbolo-transparente-dourado")}</div></div><div style="width:540px;height:320px;background:{mf};border-radius:10px;padding:44px;display:flex;flex-direction:column;justify-content:space-between"><div style="width:250px">{img("zaios-system-horizontal-reduzida-transparente-preto")}</div><div><p style="font-weight:700;font-size:20px">Nome Sobrenome</p><p style="font-size:14px;color:{gf}">Cargo · Zion Hotel Group International</p><p style="font-size:14px;color:{gf};margin-top:8px">email@exemplo.com · +55 00 00000-0000</p></div></div></div>'),
 "05-capa-modulo": (1280, 720, f'<div style="height:100%;background:{pd};display:grid;grid-template-columns:1.25fr 1fr"><div style="padding:80px 88px;display:flex;flex-direction:column;justify-content:space-between"><div style="width:230px">{img("zaios-system-horizontal-reduzida-transparente-dourado")}</div><div><p class="k" style="color:{dg};font-size:20px">Plataforma · Academy</p><p style="color:{mf};font-weight:700;font-size:74px;line-height:1.02;margin-top:18px">Seu projeto<br>na ZAIOS</p><div style="width:120px;height:4px;background:{dg};margin:26px 0"></div><p style="color:{mf};opacity:.8;font-size:24px">Cadastro, dossiê e indicadores em um só lugar</p></div></div><div style="background:{vd};display:flex;align-items:center;justify-content:center"><div style="width:58%">{img("zaios-simbolo-transparente-dourado")}</div></div></div>'),
 "06-assinatura-email": (1440, 900, f'<div style="height:100%;background:#f4f1ea;display:flex;align-items:center;justify-content:center;gap:90px"><div style="width:640px;background:#fff;padding:40px;border-radius:10px;box-shadow:0 0 0 1px #e2dccf"><p style="font-size:15px;color:{gf}">Obrigado pelo contato. Seguem os próximos passos do seu projeto.</p><div style="border-top:1px solid #e2dccf;margin-top:26px;padding-top:22px;display:flex;gap:24px;align-items:center"><div style="width:72px">{img("zaios-icone-app-preto-dourado")}</div><div><p style="font-weight:700;font-size:16px">Nome Sobrenome</p><p style="font-size:13px;color:{gf}">ZAIOS SYSTEM · Zion Hotel Group International</p><p style="font-size:12px;color:{gf};margin-top:4px">A plataforma de inteligência para desenvolvimento, gestão e operação hoteleira.</p></div></div></div><div style="width:260px;height:260px;border-radius:50%;overflow:hidden">{img("zaios-icone-app-preto-dourado")}</div></div>'),
}
for n, (w, h, corpo) in apps.items(): (A / f"{n}.html").write_text(base(w, h, corpo))
json.dump({k: [v[0], v[1]] for k, v in apps.items()}, open(A / "tamanhos.json", "w"))
print("manual e", len(apps), "aplicações")
